'use strict';

// MODULES //

var tape = require( 'tape' );
var hasProp = require( '@stdlib/assert/has-property' );
var isFunction = require( '@stdlib/assert/is-function' );
var namedtypedtuple = require( './../lib' );


// TESTS //

tape( 'main export is a function', function test( t ) {
	t.ok( true, __filename );
	t.strictEqual( typeof namedtypedtuple, 'function', 'main export is a function' );
	t.end();
});

tape( 'a tuple has an `ind2key` method', function test( t ) {
	var Point;
	var p;

	Point = namedtypedtuple( [ 'x', 'y' ] );
	p = new Point();

	t.strictEqual( hasProp( p, 'ind2key' ), true, 'returns expected value' );
	t.strictEqual( isFunction( p.ind2key ), true, 'returns expected value' );
	t.end();
});

tape( 'the method throws an error if invoked with a `this` context which is not a tuple instance', function test( t ) {
	var values;
	var Point;
	var p;
	var i;

	Point = namedtypedtuple( [ 'x', 'y' ] );
	p = new Point( [ 1, 2 ] );

	values = [
		'5',
		5,
		NaN,
		true,
		false,
		null,
		void 0,
		{},
		[],
		function noop() {}
	];
	for ( i = 0; i < values.length; i++ ) {
		t.throws( badValue( values[i] ), TypeError, 'throws an error when provided '+values[i] );
	}
	t.end();

	function badValue( value ) {
		return function badValue() {
			return p.ind2key.call( value, 0 );
		};
	}
});

tape( 'the method throws an error if provided an argument which is not an integer', function test( t ) {
	var values;
	var Point;
	var p;
	var i;

	Point = namedtypedtuple( [ 'x', 'y' ] );
	p = new Point( [ 1, 2 ] );

	values = [
		'5',
		3.14,
		NaN,
		true,
		false,
		null,
		void 0,
		{},
		[]
	];
	for ( i = 0; i < values.length; i++ ) {
		t.throws( badValue( values[i] ), TypeError, 'throws an error when provided '+values[i] );
	}
	t.end();

	function badValue( value ) {
		return function badValue() {
			return p.ind2key( value );
		};
	}
});

tape( 'the method converts a tuple index to a field name', function test( t ) {
	var Point;
	var p;

	Point = namedtypedtuple( [ 'x', 'y', 'z' ] );
	p = new Point( [ 1, 2, 3 ] );

	t.strictEqual( p.ind2key( 0 ), 'x', 'returns expected value' );
	t.strictEqual( p.ind2key( 1 ), 'y', 'returns expected value' );
	t.strictEqual( p.ind2key( 2 ), 'z', 'returns expected value' );
	t.end();
});

tape( 'the method supports negative indices', function test( t ) {
	var Point;
	var p;

	Point = namedtypedtuple( [ 'x', 'y', 'z' ] );
	p = new Point( [ 1, 2, 3 ] );

	t.strictEqual( p.ind2key( -1 ), 'z', 'returns expected value' );
	t.strictEqual( p.ind2key( -2 ), 'y', 'returns expected value' );
	t.strictEqual( p.ind2key( -3 ), 'x', 'returns expected value' );
	t.end();
});

tape( 'the method returns `undefined` if provided an out-of-bounds index', function test( t ) {
	var Point;
	var p;

	Point = namedtypedtuple( [ 'x', 'y', 'z' ] );
	p = new Point( [ 1, 2, 3 ] );

	t.strictEqual( p.ind2key( 10 ), void 0, 'returns expected value' );
	t.strictEqual( p.ind2key( -10 ), void 0, 'returns expected value' );
	t.end();
});
